// Beat grid — SHADDAI original.
//   node grid.mjs --bpm 120 --bars 8 [--offset 0] [--meter 4] > grid.json
// For music you compose yourself (or synthesize), the grid is arithmetic — no analysis needed.
// For a supplied track, use analyze.py and feed its output through the same shape.
const get = (k, d) => { const i = process.argv.indexOf('--' + k); return i > -1 ? Number(process.argv[i + 1]) : d; };
const bpm = get('bpm', 120), bars = get('bars', 8), offset = get('offset', 0), meter = get('meter', 4);

const beat = 60 / bpm;
const beats = Array.from({ length: bars * meter }, (_, i) => +(offset + i * beat).toFixed(4));
const bar = beats.filter((_, i) => i % meter === 0);
const phrase = bar.filter((_, i) => i % 4 === 0);          // every fourth bar: where the big moves go
const eighths = beats.flatMap((b) => [b, +(b + beat / 2).toFixed(4)]);

console.log(JSON.stringify({ bpm, meter, offset, seconds: +(bars * meter * beat).toFixed(3), beats, bars: bar, phrases: phrase, eighths }, null, 1));

// Sound synthesizer — SHADDAI original.
//   node synth.mjs cues.json out/sound.wav
// cues.json: [{ "at": 0.5, "voice": "tick" }, { "at": 2, "voice": "swell", "gain": 0.8 }, ...]
// Voices are small envelope-shaped oscillators; add your own to VOICES.
// Output: 48 kHz, 16-bit, mono WAV.
import { readFileSync, writeFileSync } from 'node:fs';

const RATE = 48000;
const TAU = Math.PI * 2;
const cues = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const length = Math.ceil((Math.max(...cues.map((c) => c.at)) + 3) * RATE);
const mix = new Float32Array(length);

// Own noise source so output is identical on every run.
let lcg = 0x1badf00d;
const hiss = () => ((lcg = (Math.imul(lcg, 1103515245) + 12345) >>> 0) / 2147483648) - 1;

const env = (t, attack, decay) => Math.min(1, t / attack) * Math.exp(-t / decay);
const sine = (hz, t) => Math.sin(TAU * hz * t);

// voice: [duration seconds, (t) => sample]
const VOICES = {
  tick:  [0.06, (t) => sine(2400, t) * env(t, 0.001, 0.012) * 0.45],
  blip:  [0.18, (t) => sine(520 * Math.pow(2, t * 5), t) * env(t, 0.004, 0.05) * 0.4],
  kick:  [0.55, (t) => sine(48 + 110 * Math.exp(-t * 28), t) * env(t, 0.002, 0.16) * 0.95],
  snap:  [0.20, (t) => (hiss() * 0.6 + sine(190, t) * 0.4) * env(t, 0.001, 0.045) * 0.55],
  swell: [1.20, (t) => hiss() * Math.pow(Math.min(1, t / 1.1), 2.2) * Math.exp(-Math.max(0, t - 1.1) * 30) * 0.28],
  chime: [1.40, (t) => (sine(880, t) + 0.5 * sine(1320, t) + 0.25 * sine(1760, t)) * env(t, 0.003, 0.35) * 0.22],
};

for (const cue of cues) {
  const voice = VOICES[cue.voice];
  if (!voice) throw new Error('unknown voice: ' + cue.voice);
  const [dur, fn] = voice, gain = cue.gain ?? 1, start = Math.round(cue.at * RATE);
  const n = Math.min(Math.round(dur * RATE), length - start);
  for (let i = 0; i < n; i++) mix[start + i] += fn(i / RATE) * gain;
}

// Soft-limit so stacked cues never clip.
const pcm = Buffer.alloc(44 + length * 2);
pcm.write('RIFF', 0); pcm.writeUInt32LE(36 + length * 2, 4); pcm.write('WAVE', 8); pcm.write('fmt ', 12);
pcm.writeUInt32LE(16, 16); pcm.writeUInt16LE(1, 20); pcm.writeUInt16LE(1, 22);
pcm.writeUInt32LE(RATE, 24); pcm.writeUInt32LE(RATE * 2, 28); pcm.writeUInt16LE(2, 32); pcm.writeUInt16LE(16, 34);
pcm.write('data', 36); pcm.writeUInt32LE(length * 2, 40);
for (let i = 0; i < length; i++) pcm.writeInt16LE(Math.round(Math.tanh(mix[i]) * 32767), 44 + i * 2);
writeFileSync(process.argv[3], pcm);

// Reel Forge motion kit — SHADDAI original.
// Everything here is a pure function of time `t` (seconds). No state, no timers.
//
// Springs are described the way a designer thinks: how fast (freq, Hz) and how
// bouncy (bounce, 0 = dead stop, 1 = ringing forever). A step input at time 0
// moves 0 → 1.

export const TAU = Math.PI * 2;
export const lerp = (a, b, k) => a + (b - a) * k;
export const clamp01 = (x) => (x < 0 ? 0 : x > 1 ? 1 : x);
export const remap = (x, a, b) => clamp01((x - a) / (b - a));

// Feel presets: [freq Hz, bounce]
export const FEEL = {
  crisp: [3.2, 0.12],   // buttons, toggles, cursors
  calm:  [2.1, 0.05],   // cards, camera
  heavy: [1.5, 0.02],   // big type, logos
  jelly: [2.4, 0.45],   // mascots, stickers
};

export function spring(t, freq = 2.1, bounce = 0.05) {
  if (t <= 0) return 0;
  const w = TAU * freq;
  const zeta = 1 - clamp01(bounce) * 0.98;           // bounce → damping ratio
  if (zeta >= 1) return 1 - (1 + w * t) * Math.exp(-w * t);
  const wd = w * Math.sqrt(1 - zeta * zeta);
  const decay = Math.exp(-zeta * w * t);
  return 1 - decay * (Math.cos(wd * t) + (zeta * w / wd) * Math.sin(wd * t));
}

// A value that chases a list of waypoints: each waypoint launches its own
// spring, and the results add up — so retargeting mid-flight stays smooth and
// frame N never needs frames 0..N-1.
//   waypoints: [{ at: seconds, to: value }, ...]  first one is the start value
export function chase(t, waypoints, feel = 'calm') {
  const [f, b] = Array.isArray(feel) ? feel : FEEL[feel];
  let v = waypoints[0].to;
  for (let i = 1; i < waypoints.length; i++) {
    v += (waypoints[i].to - waypoints[i - 1].to) * spring(t - waypoints[i].at, f, b);
  }
  return v;
}

// Two springs of different speed make a pill that stretches toward its target.
export function stretch(t, waypoints, size) {
  const head = chase(t, waypoints, [3.8, 0.1]);
  const tail = chase(t, waypoints, [1.9, 0.05]);
  return { from: Math.min(head, tail), to: Math.max(head, tail) + size };
}

// Content inside a changing container: appear a beat after the change begins,
// vanish a beat before the next one.
export function handoff(t, enterAt, leaveAt, lag = 0.09) {
  return Math.min(remap(t, enterAt + lag, enterAt + lag * 2.4), remap(leaveAt - lag, t, leaveAt - lag * 2));
}

// Wrap time so the last frame lands exactly on the first.
export const cycle = (t, length) => ((t % length) + length) % length;

// Deterministic randomness (SFC32). Same seed → same numbers, every render.
export function seeded(a, b = 0x9e3779b9, c = 0x243f6a88, d = 0xb7e15162) {
  return () => {
    a |= 0; b |= 0; c |= 0; d |= 0;
    const r = (((a + b) | 0) + d) | 0;
    d = (d + 1) | 0; a = b ^ (b >>> 9); b = (c + (c << 3)) | 0; c = (c << 21) | (c >>> 11); c = (c + r) | 0;
    return (r >>> 0) / 4294967296;
  };
}

// Quantize a time to the nearest beat on a grid { bpm, offset }.
export const onBeat = (t, grid, subdivision = 1) => {
  const step = 60 / grid.bpm / subdivision;
  return grid.offset + Math.round((t - grid.offset) / step) * step;
};

// Reel Forge renderer — SHADDAI original.
//   node forge.mjs [--page reel.html] [--fps 30] [--blur 0.5] [--taps 6] [--out out/reel.mp4]
//
// 1. Serves the folder on a throw-away local port (ES modules need http, not file://).
// 2. Asks the page to paint each frame and saves it as a numbered PNG in out/frames.
//    Frames that already exist are skipped, so an interrupted render resumes.
// 3. ffmpeg turns the frame folder into an H.264 MP4.
import { chromium } from 'playwright';
import { createServer } from 'node:http';
import { readFile, mkdir, access, writeFile } from 'node:fs/promises';
import { spawn } from 'node:child_process';
import { extname, join, resolve } from 'node:path';

const flag = (name, fallback) => {
  const i = process.argv.indexOf('--' + name);
  return i > -1 ? process.argv[i + 1] : fallback;
};
const root = resolve(flag('root', '.'));
const pageName = flag('page', 'reel.html');
const fps = Number(flag('fps', 30));
const shutter = Number(flag('blur', 0.5)) / fps;      // fraction of a frame the "shutter" stays open
const taps = Number(flag('taps', 6));
const outFile = flag('out', 'out/reel.mp4');
const framesDir = join(root, 'out', 'frames');

const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.mjs': 'text/javascript', '.json': 'application/json', '.png': 'image/png', '.jpg': 'image/jpeg', '.svg': 'image/svg+xml', '.woff2': 'font/woff2' };
const server = createServer(async (req, res) => {
  try {
    const path = join(root, decodeURIComponent(new URL(req.url, 'http://x').pathname));
    if (!path.startsWith(root)) throw new Error('outside root');
    res.writeHead(200, { 'content-type': MIME[extname(path)] || 'application/octet-stream' });
    res.end(await readFile(path));
  } catch { res.writeHead(404).end(); }
});
await new Promise((ok) => server.listen(0, '127.0.0.1', ok));
const base = `http://127.0.0.1:${server.address().port}/`;

await mkdir(framesDir, { recursive: true });
const browser = await chromium.launch();
const page = await browser.newPage({ deviceScaleFactor: 1 });
await page.goto(base + pageName);
await page.waitForFunction(() => typeof window.__paint === 'function');
await page.evaluate(() => document.fonts.ready);

const reel = await page.evaluate(() => window.__reel);
await page.setViewportSize({ width: reel.width, height: reel.height });
const frames = Math.round(reel.seconds * fps);
const exists = (p) => access(p).then(() => true, () => false);

for (let n = 0; n < frames; n++) {
  const file = join(framesDir, String(n).padStart(6, '0') + '.png');
  if (await exists(file)) continue;
  await page.evaluate(([t, s, k]) => window.__paint(t, s, k), [n / fps, shutter, taps]);
  await writeFile(file, await page.locator('canvas').screenshot({ type: 'png' }));
  if (n % fps === 0) console.log(`frame ${n}/${frames}`);
}
await browser.close();
server.close();

await mkdir(join(root, 'out'), { recursive: true });
const args = ['-y', '-framerate', String(fps), '-i', join(framesDir, '%06d.png'),
  '-c:v', 'libx264', '-preset', 'slow', '-crf', '15', '-pix_fmt', 'yuv420p', '-movflags', '+faststart', join(root, outFile)];
await new Promise((ok, fail) => spawn('ffmpeg', args, { stdio: 'inherit' }).on('close', (c) => (c ? fail(new Error('ffmpeg ' + c)) : ok())));
console.log('done →', outFile);
